<script setup lang="ts">
import{computed}from'vue';
import type{Match}from'../../bindings/leaguepingo/internal/core/models';
import{overviewData,roleLabels}from'../analysisData';
import RoleIcon from'./RoleIcon.vue';
const props=defineProps<{matches:Match[];scope:string}>();
const data=computed(()=>overviewData(props.matches));
const max=computed(()=>Math.max(1,...data.value.hours.map(h=>h.count)));
</script>
<template><section class="playstyle-panel"><header><h2>位置与活跃时段</h2><span>{{scope}}</span></header><div class="style-roles"><span v-for="p in data.positions" :key="p.role" :title="`${roleLabels[p.role]}，${p.count}场`"><RoleIcon :role="p.role"/><b>{{data.knownPositions?`${Math.round(p.count*100/data.knownPositions)}%`:'—'}}</b></span></div><div class="activity-heading"><h3>对局开始时间</h3><span>本地时间 · 0–{{max}} 场/小时</span></div><div class="activity-hours" :aria-label="`${data.timedGames}场已记录开始时间的对局`"><span v-for="hour in data.hours" :key="hour.hour" :title="`${hour.hour}:00–${hour.hour}:59 · ${hour.count}场`"><i :style="{height:`${hour.count*100/max}%`}"/></span></div><div class="activity-axis"><span>0时</span><span>6时</span><span>12时</span><span>18时</span><span>23时</span></div></section></template>
